//! Builds the `.rc` source text for a Windows icon + `VERSIONINFO` resource. Pure and
//! dependency-free (unlike `build.rs`, which also links `embed-resource` to actually
//! invoke `llvm-rc`), so it is unit-testable by compiling this file standalone:
//! `rustc --edition 2021 --test packaging/windows/version_rc.rs`.
//!
//! Included via `#[path]` from both `crates/kgraf-shell/build.rs` (`kgraf-app`)
//! and `crates/kgraf-cli/build.rs` (`kgraf`), so the two binaries' resources are
//! generated by one reviewed function rather than two near-duplicate `format!` calls.

/// Builds the `.rc` source: an `ICON` statement, an `RT_MANIFEST` statement (L6 --
/// `packaging/windows/manifest.rs`'s `MANIFEST_XML`), and a `VERSIONINFO` block.
/// `version` must be `MAJOR.MINOR[.PATCH]` (this workspace's convention, `X.Y.Z`); a
/// missing or non-numeric component defaults to 0. A fourth `FILEVERSION`/
/// `PRODUCTVERSION` component of 0 is appended, since Windows expects four numeric
/// parts and Cargo's semver only carries three.
pub fn windows_resource_rc(
    internal_name: &str,
    original_filename: &str,
    description: &str,
    version: &str,
    ico_path: &str,
    manifest_path: &str,
) -> String {
    let mut parts = version.split('.');
    let major: u32 = parts.next().and_then(|s| s.parse().ok()).unwrap_or(0);
    let minor: u32 = parts.next().and_then(|s| s.parse().ok()).unwrap_or(0);
    let patch: u32 = parts.next().and_then(|s| s.parse().ok()).unwrap_or(0);
    // Backslashes in an RC string/path are escape sequences; the generated .ico/
    // .manifest paths are always OUT_DIR-relative and forward-slash on this macOS host,
    // but escape any stray backslash defensively rather than assume the host path
    // separator.
    let ico_path_escaped = ico_path.replace('\\', "\\\\");
    let manifest_path_escaped = manifest_path.replace('\\', "\\\\");

    format!(
        r#"IDI_ICON1 ICON "{ico_path_escaped}"

#define RT_MANIFEST 24
1 RT_MANIFEST "{manifest_path_escaped}"

1 VERSIONINFO
FILEVERSION {major},{minor},{patch},0
PRODUCTVERSION {major},{minor},{patch},0
FILEFLAGSMASK 0x3fL
FILEFLAGS 0x0L
FILEOS 0x40004L
FILETYPE 0x1L
FILESUBTYPE 0x0L
BEGIN
    BLOCK "StringFileInfo"
    BEGIN
        BLOCK "040904b0"
        BEGIN
            VALUE "CompanyName", "Marco Cross"
            VALUE "FileDescription", "{description}"
            VALUE "FileVersion", "{version}.0"
            VALUE "InternalName", "{internal_name}"
            VALUE "LegalCopyright", "Apache-2.0"
            VALUE "OriginalFilename", "{original_filename}"
            VALUE "ProductName", "kGraf"
            VALUE "ProductVersion", "{version}.0"
        END
    END
    BLOCK "VarFileInfo"
    BEGIN
        VALUE "Translation", 0x409, 1200
    END
END
"#
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rc_carries_the_icon_statement_and_four_part_version() {
        let rc = windows_resource_rc(
            "kgraf-app",
            "kgraf-app.exe",
            "desc",
            "0.1.0",
            "/tmp/x.ico",
            "/tmp/x.exe.manifest",
        );
        assert!(rc.contains(r#"IDI_ICON1 ICON "/tmp/x.ico""#));
        assert!(rc.contains("FILEVERSION 0,1,0,0"));
        assert!(rc.contains(r#"VALUE "FileVersion", "0.1.0.0""#));
        assert!(rc.contains(r#"VALUE "ProductName", "kGraf""#));
        assert!(rc.contains(r#"VALUE "InternalName", "kgraf-app""#));
        assert!(rc.contains(r#"VALUE "OriginalFilename", "kgraf-app.exe""#));
    }

    #[test]
    fn rc_carries_the_rt_manifest_statement() {
        let rc = windows_resource_rc(
            "x",
            "x.exe",
            "d",
            "1.0.0",
            "/tmp/x.ico",
            "/tmp/x.exe.manifest",
        );
        assert!(rc.contains("#define RT_MANIFEST 24"));
        assert!(rc.contains(r#"1 RT_MANIFEST "/tmp/x.exe.manifest""#));
    }

    #[test]
    fn missing_version_parts_default_to_zero() {
        let rc = windows_resource_rc("x", "x.exe", "d", "1", "/tmp/x.ico", "/tmp/x.exe.manifest");
        assert!(rc.contains("FILEVERSION 1,0,0,0"));
        assert!(rc.contains("PRODUCTVERSION 1,0,0,0"));
    }

    #[test]
    fn non_numeric_component_defaults_to_zero_instead_of_panicking() {
        let rc = windows_resource_rc(
            "x",
            "x.exe",
            "d",
            "1.beta.0",
            "/tmp/x.ico",
            "/tmp/x.exe.manifest",
        );
        assert!(rc.contains("FILEVERSION 1,0,0,0"));
    }

    #[test]
    fn a_backslash_in_the_icon_and_manifest_path_is_escaped() {
        let rc = windows_resource_rc(
            "x",
            "x.exe",
            "d",
            "1.0.0",
            r"C:\out\icon.ico",
            r"C:\out\x.exe.manifest",
        );
        assert!(rc.contains(r#"IDI_ICON1 ICON "C:\\out\\icon.ico""#));
        assert!(rc.contains(r#"1 RT_MANIFEST "C:\\out\\x.exe.manifest""#));
    }
}
